-- 2908 🏋️ Exercises from the book "roberto-de-zerbi-92-build-up-passing-combinations-and-attacking-positional-pract" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'roberto-de-zerbi-92-build-up-passing-combinations-and-attacking-positional-pract');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('5v2 one-touch rondo, pressing pair', 'rondo', 'overload', 'in_possession', 13, 13, 'Rondos 1', 'De Zerbi (Brighton)', 'Keep the ball with short one-touch passing while two defenders press together to win it.', 'Groups of 7 in an 8 yard square: 5 on the edges (who may move inside the area) and 2 bibbed defenders in the middle.', 'The five circulate the ball with one touch each; the two defenders work as a pair to press, shut passing angles and win the ball.', 'Outside players 1 touch. If the defenders win it within the first 10 passes, both swap with 2 outside players.', NULL, 'Defenders press as a unit and close angles; attackers stay in the square and keep passes short and crisp.', '5v2', 7, 7, '8 x 8 yards', 7.3, 7.3, NULL, false, false, false, NULL, 10),
  ('4v2 rondo with central floater', 'rondo', 'overload', 'in_possession', 14, 14, 'Rondos 2', 'De Zerbi (Brighton)', 'Create passing angles with a floating middle player while a defending pair presses to win the ball.', 'Groups of 7 in an 8 yard square: 4 outside players, 1 floater in the middle helping the team in possession, 2 bibbed defenders.', 'The four outside players keep the ball, using the floater to split the defenders; the two defenders press together, closing lanes to win it.', 'Mainly 1 touch (2 allowed). On a turnover the 2 players who touched the ball last become the defenders.', NULL, 'Floater keeps finding space between the pressers; defenders cut lanes together.', '4+1v2', 7, 7, '8 x 8 yards', 7.3, 7.3, NULL, false, false, false, NULL, 20),
  ('6v2 rondo with central floater', 'rondo', 'overload', 'in_possession', 15, 15, 'Rondos 3', 'De Zerbi (Brighton)', 'Find angles through a central floater to keep the ball against a pressing pair.', 'Groups of 9 in an 8 x 10 yard area: 6 outside, 1 floater in the middle, 2 bibbed defenders.', 'Six outside players circulate with help from the floater; the defending pair presses and blocks lanes to win the ball.', 'Mainly 1 touch (2 allowed). The 2 players who touched the ball last before it was lost swap in as defenders.', NULL, 'Use the floater to play through the middle; defenders press in pairs.', '6+1v2', 9, 9, '8 x 10 yards', 9.1, 7.3, NULL, false, false, false, NULL, 30),
  ('8v2 one-touch rondo, pressing pair', 'rondo', 'overload', 'in_possession', 16, 16, 'Rondos 4', 'De Zerbi (Brighton)', 'Maintain possession with short one-touch passes against two defenders pressing together.', 'Groups of 10 in a 10 yard square: 8 around the outside (may step inside the area) and 2 bibbed defenders.', 'The eight keep the ball with one-touch passes; the two inside defenders press as a pair to close angles and win it. De Zerbi sometimes joined in.', 'Outside players 1 touch. If the defenders win the ball within the first 10 passes, both swap with 2 outside players.', NULL, 'Short, sharp passing; defenders work together to press.', '8v2', 10, 10, '10 x 10 yards', 9.1, 9.1, NULL, false, false, false, NULL, 40),
  ('8v2 rondo with central floater', 'rondo', 'overload', 'in_possession', 17, 17, 'Rondos 5', 'De Zerbi (Shakhtar Donetsk)', 'Use a middle floater to create angles and keep the ball against a pressing pair.', 'Groups of 11 in a 10 x 12 yard area: 8 outside, 1 floater inside, 2 bibbed defenders.', 'Outside players keep the ball with the floater''s help; the two defenders press together to cut lanes and win it.', 'Mainly 1 touch (2 allowed). The 2 players who last touched the ball before losing it become defenders.', NULL, 'Play through the floater; defending pair closes angles together.', '8+1v2', 11, 11, '10 x 12 yards', 11.0, 9.1, NULL, false, false, false, NULL, 50),
  ('4-player one-two and rotation pattern', 'passing_unopposed', 'unopposed', 'in_possession', 20, 21, 'Passing Combinations 1', 'De Zerbi (Brighton)', 'Rehearse short combinations, supporting runs and well-timed movement with rotating positions.', 'Groups of 4 set out in a line in a narrow channel around a central mannequin: two players at one end, one at the other end and one in the middle.', 'A plays a one-two with B, B passes long to C at the far end and follows; C plays a one-two with the middle player then passes to A2 at the start end, and the sequence keeps going with players rotating into the position they passed to.', NULL, 'Variation 2: two players at the ends and two in the middle set diagonally either side of the mannequin; short combinations (pass, diagonal, inside pass round the mannequin, set back, one-twos), with the middle players occasionally swapping sides.', 'Time the movement off the mannequin to arrive as the ball does; support at angles.', 'groups of 4', 4, 4, NULL, NULL, NULL, NULL, false, false, false, NULL, 60),
  ('Diamond pole circuit, open up at speed', 'passing_unopposed', 'unopposed', 'in_possession', 22, 23, 'Passing Combinations 2', 'De Zerbi (Brighton)', 'Open the body to receive on the half-turn at angles and move the ball at speed with strong passes.', 'A diamond of poles with a player at each point (A to D) plus two wide players E1 and E2 at the side points.', 'Each player moves off his pole at an angle and receives on the half-turn; the ball goes A to B to C to D to E1 and back to start, players following their pass. After a set, repeat to the other side using E2.', '2 touches (control and pass).', 'Variation 2: free decision-making, 1 touch where possible - players choose the route (e.g. skip a pole with a longer pass and set back).', 'Open up, give the right angle, speed and strength of pass.', '6+', 6, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 70),
  ('Two-ball passing diamond, switch direction', 'passing_unopposed', 'unopposed', 'in_possession', 24, 24, 'Passing Combinations 3a', 'De Zerbi (Brighton)', 'High speed of play with two balls and quick reactions when the direction is switched.', 'A diamond of four mannequins with players at each point and two balls in play at once, starting from opposite points.', 'Players drop off their mannequin at an angle, open up, control and pass on around the diamond, following their pass; both balls travel the same way.', '2 touches (control out of body + pass).', 'On the coach''s call both balls reverse direction (anticlockwise to clockwise).', 'Timing comes off the first touch; touch and play quickly.', '8+', 8, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 80),
  ('Diamond circuit: one-two, set, switch, give-go', 'passing_unopposed', 'unopposed', 'in_possession', 25, 25, 'Passing Combinations 3b', 'De Zerbi (Brighton)', 'Combine one-twos, set passes, a switch across the diamond and a give-and-go with checking movements.', 'Diamond of mannequins with players at each point (and second players waiting), coach in the centre observing.', 'A one-two with B, A passes to C who sets for the oncoming B, B switches across to D, D sets back for C round the mannequin, C passes to A2 who sets for D, and D switches across to restart. Players rotate round the circuit.', NULL, NULL, 'Check away before moving to receive; sets timed for the runner.', '8+', 8, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 90),
  ('One-touch diamond circuit ending in dribble', 'passing_unopposed', 'unopposed', 'in_possession', 26, 26, 'Passing Combinations 4', 'De Zerbi (Benevento)', 'Play a one-two, set, switch and give-and-go sequence at one touch.', 'Diamond of mannequins with players at each point, as in 3b.', 'Same first steps as 3b, but C passes into space for D who moves round the mannequin, receives and dribbles back to the start so the circuit carries on with A2.', 'Steps up to the final pass all 1 touch.', NULL, 'Check away then come to receive; quality one-touch passes.', '8+', 8, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 100),
  ('Diamond with central player, opposite movements', 'passing_unopposed', 'unopposed', 'in_possession', 27, 28, 'Passing Combinations 5', 'De Zerbi (Shakhtar Donetsk)', 'Use opposite movements to open up for support play around a central player.', 'Diamond of mannequins with a central mannequin; players at each point (D1 and D2 at the two sides).', 'A passes beside the central mannequin for B to drop and play a one-two, A then passes past the end mannequin for C who opens up and touches past it, C passes diagonally to D2 who checks, opens up and finishes the circuit to A2. Repeat to the other side via D1.', 'Variation 1: C may use 2 touches.', 'Variation 2: whole sequence at 1 touch - one-two, pass, lay-off and give-and-go (C sets back for B''s forward run).', 'Check away before receiving; open up to take a forward touch past the mannequin.', '6+', 6, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 110),
  ('Two-ball hexagon circuit into small goals', 'passing_unopposed', 'unopposed', 'in_possession', 29, 30, 'Passing Combinations 6', 'De Zerbi (Brighton)', 'Check off the pole to open up and receive, then finish with a pass into a small goal.', 'Hexagon of poles/mannequins with the same set-up on both sides, two balls starting from A1 and A2, and two small goals at the start end.', 'A passes to B who opens up outside the mannequin and plays to C; C passes diagonally to D in the centre, who opens up outside the pole and passes into the small goal, then joins the opposite group.', 'D may use 2 touches.', 'Variation 2: A plays a one-two with B, B passes to C who sets for B''s run, B passes inside to D who sets for C round the mannequin, C slides a through pass between the poles for D, and D finishes into the small goal.', 'Every player checks off his pole before receiving; open up.', '10+', 10, NULL, NULL, NULL, NULL, NULL, true, false, true, NULL, 120),
  ('Two-ball ''off the pole'' hexagon circuit', 'passing_unopposed', 'unopposed', 'in_possession', 31, 35, 'Passing Combinations 7', 'De Zerbi (Brighton)', 'Receive off the pole on the correct side, inside or outside, and keep two balls moving round a hexagon.', 'Hexagon of poles with the same set-up on both sides; two balls start from A1 and A2 at once.', 'A passes to B who opens up and plays to C; C opens up behind the pole, moves the ball forward at an angle and plays into D in the centre, who does the same and passes back to the start.', 'Variation 1 is 2-touch.', 'Five variations: 1 inside/outside pass and receive (2 touches); 2 pass inside to out with one-twos; 3 inside to out with give-and-go; 4 receive, one-two and play forward; 5 central support with 2 and 3 player combinations. In all, the coach can call to reverse both balls.', 'Touch, play, open up; check away before receiving.', '10+', 10, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 130),
  ('Inside/outside receiving angle circuit, 2-touch', 'passing_unopposed', 'unopposed', 'in_possession', 36, 36, 'Passing Combinations 8', 'De Zerbi (Shakhtar Donetsk)', 'Choose an inside or outside receiving angle and control with quality on a continuous circuit.', 'A large circuit of mannequins with corner and middle players (A to H), mannequins behind which they open up to receive.', 'The ball travels A to H round the circuit, each player opening up behind his mannequin and passing to the right or left of the next mannequin; the middle wide players decide whether to receive inside or outside.', '2 touches (control + pass).', 'On the coach''s cue the direction reverses to clockwise.', 'Quality of pass and quality of first touch.', '9+', 9, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 140),
  ('Support angles circuit with central players', 'passing_unopposed', 'unopposed', 'in_possession', 37, 37, 'Passing Combinations 9', 'De Zerbi (Brighton)', 'Open up at the right angle to support and play forward through central players.', 'Mannequins around the edge and in the centre; players A to H, with D and H in the middle.', 'A passes to B in the centre, B plays a one-two with C and times a pass for C round the mannequin; C to D in the centre, D to E who opens up; E to F, F one-two with G and times the pass round the mannequin; G to H in the centre who returns to the start.', NULL, 'After a set period the direction switches to clockwise.', 'Middle players check away, receive and open up for the next pass; always give the right angle.', '9+', 9, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 150),
  ('Diagonal angles circuit with ''bounce'' call', 'passing_unopposed', 'unopposed', 'in_possession', 38, 38, 'Passing Combinations 10', 'De Zerbi (Brighton)', 'Open up away from the pole to receive at diagonal angles, with inside/outside support and quick reactions to a coach call.', 'Hexagon of poles, same set-up on both sides, two balls starting from A1 and A2, with extra players waiting at A3/A4.', 'A to B to C to D round each side, players checking off their poles to receive and pass at speed; C plays a one-two with D, who moves inside for the return.', NULL, 'When the coach calls ''Bounce'' the receiving player sets the ball back so his teammate plays the next pass instead.', 'Strong passes; open up away from the pole.', '10+', 10, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 160),
  ('Double triangle one-two circuit, match warm-up', 'passing_unopposed', 'unopposed', 'in_possession', 39, 39, 'Passing Combinations 11', 'De Zerbi (Brighton)', 'Pre-match passing warm-up mixing control-and-pass with one-touch give-and-gos.', 'Two triangles of cones, the same at both ends, with two balls starting from A1 and A2.', 'A plays a one-two with B then passes at an angle to C; C plays a give-and-go with B and passes to D, who opens up, receives and passes forward to the other start position. Players rotate round the circuit.', '2 touches for control and pass, 1 touch for give-and-gos.', NULL, 'Move off the cone to receive; timing of the give-and-go.', '8+', 8, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 170),
  ('Build-up receiving angles circuit, two balls', 'passing_unopposed', 'unopposed', 'in_possession', 40, 41, 'Passing Combinations 12', 'De Zerbi (Brighton)', 'Find receiving angles to play through lines with support play.', 'A triangle of cones near the start and a rhombus further up, with mannequins; players A to H. Second ball starts as soon as H receives.', 'A to B to C in a triangle, C diagonal to D, D to E, E to F; F sets back for E who passes to G, G plays a give-and-go with F to receive round the mannequin, then passes to H who dribbles back to the start.', NULL, 'Variation 2: lay-offs plus give-and-go - C passes to E who sets back for D''s curved run, D passes forward to F. After a set time the circuit is repeated to the right on the yellow cones.', 'Check off the cones to receive; open up around the mannequin.', '9+', 9, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 180),
  ('Positional receiving circuit: F-AM-W-CB-DM', 'passing_unopposed', 'unopposed', 'in_possession', 42, 42, 'Passing Combinations 13', 'De Zerbi (Sassuolo)', 'Rehearse positioning, receiving and support movements in match positions.', 'Mannequins placed around a half-pitch shape with players in positions: forward, attacking midfielder, defensive midfielder, both wingers and a centre back.', 'F dribbles and passes to AM, AM checks and plays wide to LW, LW dribbles in and passes to CB, CB dribbles forward and plays wide to RW who checks, RW finds DM who takes a forward touch and passes to the start; players rotate F to AM to LW to CB to RW to DM.', '1-3 touches.', 'After a set period the direction switches to clockwise.', 'Accurate movement and positioning; check before moving to receive.', '7+', 7, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 190),
  ('Positional build-up rhombus combinations', 'passing_unopposed', 'unopposed', 'in_possession', 43, 45, 'Passing Combinations 14', 'De Zerbi (Sassuolo)', 'Build-up combinations and movements between back line and midfield in positional roles.', 'Two rhombuses of cones: back one with LB, CB, RB and DM, front one with DM, LCM, RCM and F.', 'LB to CB, CB to DM who drops and plays to RB, RB and CB exchange, CB to LB, LB to DM who plays wide to LCM, LCM to F who sets for DM, DM to RCM to F, F one-two with RCM and across to LCM, LCM to DM to restart.', 'Variations 1-2: 2 touches (control + pass). Variation 3: 1 touch, 2 when needed.', 'Variation 2: coaching timing of movement - RB carries forward and back and the DM curves to receive; Variation 3: faster one-touch combinations with switches, players moving in sync with the ball.', 'Accurate movement and positioning; timing of moves inside and back.', '8', 8, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 200),
  ('One-touch break-the-lines double circuit', 'passing_unopposed', 'unopposed', 'in_possession', 46, 46, 'Passing Combinations 15', 'De Zerbi (Brighton)', 'One-touch combinations to break lines through a central box midfield.', 'Cones and mannequins around the centre circle, same on both sides, two balls starting from A and A2.', 'A plays a one-two with B then passes to C, C plays a give-and-go with B to receive beyond the mannequin, then C to D, D to E and E back to the start; players rotate A to F.', 'All 1 touch.', NULL, 'Check before moving to receive.', '12+', 12, NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 210),
  ('3v3 plus 4 outside supports keep-ball', 'rondo', 'overload', 'in_possession', 74, 74, 'Positional Possession Games: Practice 1', 'De Zerbi (Sassuolo)', 'Quick combinations and clever support play while keeping the ball under collective pressing.', '10 yard square with 3 whites v 3 reds inside and 4 blue neutrals, one on each side, standing in for CB, LB, RB and F; inside whites act as DM, CB and CM.', 'Whites keep the ball with help from the 4 outside blues while the reds press together to shut passing angles and win it.', 'If reds win the ball they swap roles with the whites; blues always play with the team in possession.', NULL, 'Combine quickly, support at good angles, defenders press as a unit.', '3v3+4', 10, 10, '10 x 10 yards', 9.1, 9.1, NULL, false, false, false, NULL, 220),
  ('5v5 plus 4 end-to-end possession', 'positional_game', 'overload', 'in_possession', 75, 75, 'Positional Possession Games: Practice 2', 'De Zerbi (Sassuolo)', 'Keep possession and move the ball from one end to the other and back through positional roles.', '15 yard square: 5 whites (CB, LB, RB, DM, CM) v 5 reds, 2 yellow jokers inside, and 2 blue end players acting as the other CB and the forward.', 'Whites, helped by the jokers and end players, circulate to reach one end player, then work the ball back to the other end; reds press together to win it.', 'Jokers and end players play for the team in possession; reds switch roles with whites when they win the ball.', NULL, 'Hold positions, find the free man, play end to end and back.', '5v5+4', 14, 14, '15 x 15 yards', 13.7, 13.7, NULL, false, false, true, NULL, 230),
  ('4v4 plus 3 central positional possession', 'possession', 'overload', 'in_possession', 76, 76, 'Positional Possession Games: Practice 3', 'De Zerbi (Brighton)', 'Keep the ball in the central area while staying in positional roles.', 'Area around the centre circle: 4 blues (2 DMs, LW, RW) v 4 reds inside, with 3 yellow neutrals on the edges as RB, LB and AM; coach with balls at the side.', 'Coach plays in; blues plus yellows keep possession against the 4 pressing reds, all moving to offer support while holding their positions.', 'Two-touch, firm passes; reds swap with blues when they win it, yellows always support the team on the ball.', NULL, 'Read the picture before receiving, strong passes, keep positional shape.', '4v4+3', 11, 11, NULL, NULL, NULL, NULL, false, false, false, NULL, 240),
  ('4v4 plus 4 three-team possession centre', 'possession', 'overload', 'in_possession', 77, 77, 'Positional Possession Games: Practice 4', 'De Zerbi (Sassuolo)', 'Positional keep-ball with full backs and wingers giving width and support.', 'Central area with 3 teams of 4: whites inside (2 CBs, DM, CM), blues on the outside as LB, RB, LW, RW, reds defending inside.', 'Coach passes in; whites and blues keep the ball against the 4 pressing reds, everyone moving to support, especially the full backs.', 'If reds win the ball they swap with the whites; blues stay as the supporting team.', NULL, 'Support angles, full backs move to offer options, defenders press together.', '4v4+4', 12, 12, NULL, NULL, NULL, NULL, false, false, false, NULL, 250),
  ('6v6 plus 4 build-up possession game', 'possession', 'overload', 'in_possession', 78, 78, 'Positional Possession Games: Practice 5', 'De Zerbi (Sassuolo)', 'Possession, support play, positioning and collective pressing in a build-up shape.', 'Large central area: whites (2 CBs, LB, RB, LW, F) and blues (DM, LCM, RCM, RW) together v 6 reds; coach with balls at the bottom.', 'Whites and blues keep the ball in a 4-3-3 style shape against 6 pressing reds; coach stops to coach positions and pressure.', 'When reds win it they swap with the whites; blues stay unchanged as supports.', NULL, 'Possession first, support and positioning; defending side presses collectively.', '6v6+4', 16, 16, NULL, NULL, NULL, NULL, false, false, false, NULL, 260),
  ('7v7 plus 2 jokers GK to GK build-up', 'positional_game', 'overload', 'in_possession', 79, 79, 'Positional Possession Games: Practice 6', 'De Zerbi (Shakhtar Donetsk)', 'Build up from a goalkeeper and play through the opposition to reach the GK at the other end.', 'Marked area in midfield with 2 teams of 7 (back 4, 2 DMs, 1 AM from a 4-2-3-1), 2 yellow jokers inside acting as winger and forward, and a GK at each end as end player.', 'A GK starts; the team keeps the ball and plays through the other side to find the opposite GK, who passes to a defender of the other team, which then attacks the other way.', 'Jokers play for the team in possession; a team winning the ball goes back to its GK to restart the build-up.', NULL, 'Patient build-up from GK, use jokers as winger and forward, play through lines.', '7v7+2+2 GKs', 18, 18, NULL, NULL, NULL, NULL, false, true, true, NULL, 270),
  ('CB build-up to DM, diagonal through ball', 'passing_opposed', 'passive', 'in_possession', 82, 82, 'Positional Build-up Play: Practice 1 (5+GK v1)', 'De Zerbi (Sassuolo)', 'Build up through the centre, find the DM to break the lines, finish with a diagonal through pass.', 'Half pitch split into channels with mannequins: GK, LCB, RCB, LB, RB and DM against 1 red defender and 3 coaches giving passive pressure.', 'Coach lofts to GK, GK to RCB, across to LCB who carries into the next zone; when blocked he plays back to RCB, who is pressed and finds the DM shifting across; DM sets for the oncoming LCB, who plays a diagonal through pass between the full back and centre back mannequin.', NULL, 'Leads into the 5+GK v2 variation with full backs involved.', 'Full backs keep making supporting runs; carry forward when blocked pass is shut.', '5+GK v1 (+3 coaches)', 7, 10, NULL, NULL, NULL, NULL, false, true, true, NULL, 280),
  ('CB build-up via DM lay-off, vertical through ball', 'passing_opposed', 'passive', 'in_possession', 83, 83, 'Positional Build-up Play: Practice 2 (5+GK v1)', 'De Zerbi (Sassuolo)', 'Build up through the centre using the DM to break the lines and finish with a straight through pass.', 'Same as Practice 1: GK, 2 CBs, 2 FBs and DM v 1 red, coaches applying passive pressure, mannequins as defenders.', 'Coach to GK, GK to RCB who carries; pass blocked so he plays across to LCB who passes into the DM; DM, back to goal, lays off to the oncoming RCB who carries over halfway, then LCB plays a vertical pass into the space between full back and centre back mannequin.', NULL, NULL, 'DM shifts to receive, lay-off to the third man, full backs support throughout.', '5+GK v1 (+3 coaches)', 7, 10, NULL, NULL, NULL, NULL, false, true, true, NULL, 290),
  ('Reset shape then bait the press', 'passing_opposed', 'passive', 'in_possession', 84, 86, 'Positional Build-up Play: Practice 3a + 3b (5+GK v2)', 'De Zerbi (Sassuolo)', 'React to the ball with pressing movements, reset into build-up shape from the GK, then bait pressure and pick the moment to advance.', 'Half pitch with channels and mannequins: GK, 2 CBs, 2 FBs and DM v 2 reds (forward plus a midfielder), coaches giving passive pressure; CBs drop either side of the GK, FBs wide outside the box.', 'Coach dribbles to one side and the whites make pressing movements, then he turns and lofts to the GK and they drop into build-up positions. GK to LCB, DM marked so drops to RCB; RCB to LCB under pressure, LCB carries and finds LB, LB switches diagonally to the oncoming RCB, who dribbles to halfway and passes to the coach.', NULL, '3b(2) variation: the red forward drops off first, so RCB carries into the second zone before being closed, plays to LCB who also dribbles forward and finds LB, then switch back to RCB.', 'Move as a unit with the ball, reset fast, use the free CB to carry when not pressed.', '5+GK v2 (+coaches)', 8, 11, NULL, NULL, NULL, NULL, false, true, true, NULL, 300),
  ('Coached pattern through two pressure lines', 'passing_opposed', 'opposed', 'in_possession', 87, 87, 'Positional Build-up Play: Practice 4 (8+GK v6)', 'De Zerbi (Sassuolo)', 'Learn set patterns to play out from the back through the first and second lines of pressure.', 'Two-thirds pitch with channels: GK and 8 players (back 4, DM, LCM, RCM, F) v 6 reds; the coach takes the LCB role.', 'LB passes to coach (as LCB), across to RCB who is pressed, back to coach, into DM who sets for RCB; RCB plays into RCM, who sets back for DM, DM finds the forward who sets for the oncoming LCM. Coach stops at key steps to explain options (e.g. CBs push up, RB tucks in).', NULL, 'Variation: instead of passing to F, DM dribbles forward and plays a through pass beyond the end line.', 'Bounce passes to the third man, receive facing forward, DM can drive if unmarked.', '8+GK v6', 15, 15, NULL, NULL, NULL, NULL, false, true, true, NULL, 310),
  ('Forward lay-off for DM third-man run', 'passing_opposed', 'opposed', 'in_possession', 88, 88, 'Positional Build-up Play: Practice 5 (8+GK v6)', 'De Zerbi (Sassuolo)', 'Play out from the GK to the forward, whose lay-off releases the DM''s third-man run beyond midfield.', 'As Practice 4: GK and 8 v 6 reds in a channelled two-thirds pitch, coach starts with balls.', 'Coach to GK, players take positions; GK to RCB who touches forward under pressure, to DM (marked) and back to LCB in space; LCB carries and finds LCM who turns away from his marker and plays into F; F sets for DM''s deep run and DM drives beyond the end line for F''s curved run.', NULL, NULL, 'Turn away from pressure, lay-off to the runner, time the curved run in behind.', '8+GK v6', 15, 15, NULL, NULL, NULL, NULL, false, true, true, NULL, 320),
  ('Right side build-up, CM runs in behind', 'passing_opposed', 'opposed', 'in_possession', 89, 89, 'Positional Build-up Play: Practice 6 (8+GK v6)', 'De Zerbi (Sassuolo)', 'Build up down the right and release the central midfielder on a third-man run behind the defence.', 'As Practice 4: GK and 8 v 6 reds, channelled area, coach starts.', 'GK to RCB, who carries forward when not pressed, passes to RB, who finds DM inside; DM, having shifted right, splits the red midfield to F; RCM makes a third-man run past the line and receives F''s wall pass in behind.', NULL, NULL, 'CB drives into free space; F and DM shift to the ball side.', '8+GK v6', 15, 15, NULL, NULL, NULL, NULL, false, true, true, NULL, 330),
  ('Patient build-up, double one-two switch', 'passing_opposed', 'opposed', 'in_possession', 90, 90, 'Positional Build-up Play: Practice 7 (8+GK v6)', 'De Zerbi (Sassuolo)', 'Be patient through the GK, switch twice and use quick one-twos to break the lines.', 'As Practice 4: GK and 8 v 6 reds, channelled area.', 'GK to LCB, to LB, back to GK when pressed; GK to RCB (pressed), into RCM who drops; RCM one-twos with DM to beat his man, then one-twos with LCM moving forward, then passes for F''s run on the right.', NULL, NULL, 'Use the GK to switch, support close for quick one-twos.', '8+GK v6', 15, 15, NULL, NULL, NULL, NULL, false, true, true, NULL, 340),
  ('Build-up with DM give-and-go to forward', 'passing_opposed', 'opposed', 'in_possession', 91, 91, 'Positional Build-up Play: Practice 8 (8+GK v6)', 'De Zerbi (Sassuolo)', 'Break the midfield line with a one-two and play into the forward''s run.', 'As Practice 4: GK and 8 v 6 reds, channelled area.', 'GK to RCB, across to LCB under the forward''s pressure, to LB, inside to DM who drops, back to LCB and across to RCB; RCB plays into RCM inside as DM shifts across; RCM and DM play a give-and-go to break the line and finish with a pass for F''s movement.', NULL, NULL, 'DM shifts across to support; one-two to get past the midfield line.', '8+GK v6', 15, 15, NULL, NULL, NULL, NULL, false, true, true, NULL, 350),
  ('Left throw-in build-up, CB drives', 'passing_opposed', 'opposed', 'in_possession', 92, 92, 'Positional Build-up Play: Practice 9 (8+GK v6)', 'De Zerbi (Sassuolo)', 'Build up from a left-side throw-in and let the far centre back exploit space to carry forward.', 'As Practice 4 with the restart a throw-in on the left touchline: 8+GK v 6 reds.', 'LB throws to the marked DM, who plays back to LB; LB carries and passes inside to RCB (LCB dropped to drag the forward away); RCB dribbles into the open centre; RCM takes his marker away and RCB finds F shifting across, who plays for RCM''s third-man run.', NULL, NULL, 'Drag markers to open lanes, CB drives into space.', '8+GK v6', 15, 15, NULL, NULL, NULL, NULL, false, true, true, NULL, 360),
  ('Right throw-in build-up, CB drives', 'passing_opposed', 'opposed', 'in_possession', 93, 93, 'Positional Build-up Play: Practice 10 (8+GK v6)', 'De Zerbi (Sassuolo)', 'Build up from a right-side throw-in, switch, and let the far centre back carry into space.', 'As Practice 4 with a throw-in on the right touchline: 8+GK v 6 reds.', 'RB throws to the marked DM, back to RB, back to RCB who has dropped, who switches to LCB; LCB dribbles into open space while others run forward, passes inside to DM, to RCM, and RCM finds RB''s long overlapping run beyond the end line.', NULL, NULL, 'CB drops to create time to switch; full back runs from deep.', '8+GK v6', 15, 15, NULL, NULL, NULL, NULL, false, true, true, NULL, 370),
  ('5v3 central build-up to small goals', 'small_sided_game', 'overload', 'in_possession', 94, 94, 'Positional Build-up Play: Practice 11', 'De Zerbi (Sassuolo)', 'Build up through the centre, break the midfield line and score in small goals.', 'Central area with a finish zone and 2 small goals at the far end: whites 2 CBs and 3 CMs v 3 red midfielders starting in marked spots.', 'Coach passes to a CB; whites combine (often CB-DM-CB triangle) to beat the reds, find LCM or RCM past the line, who dribbles into the finish zone and scores.', NULL, NULL, 'Use the triangle depending on whether DM is marked or free; CB steps forward to draw a defender.', '5v3', 8, 8, NULL, NULL, NULL, NULL, true, false, true, NULL, 380),
  ('10v6 plus 4 possession, switch, finish', 'phase_of_play', 'overload', 'in_possession', 95, 95, 'Positional Build-up Play: Practice 12', 'De Zerbi (Sassuolo)', 'Build up with patience, consolidate and switch play before attacking the end zone to score.', 'Pitch split into a low zone and an end zone with a full goal and GK: 10 whites in a 4-3-3 v reds in a 4-3-3 shape; 2 winger-only zones on the flanks of the low zone.', 'Whites keep the ball and switch play (e.g. double switch winger to winger) in the low zone, then play into the end zone with intent; the 4 red defenders become active and drop to defend while whites combine quickly to score.', 'Wingers only in their side zones; coaches stress possession and switching rather than attacking at the first chance.', NULL, 'Consolidate first, switch, then quick combinations to finish.', '10v6 (+4)', 21, 21, NULL, NULL, NULL, NULL, true, true, true, NULL, 390),
  ('10v6 build-up then 5v4 attack', 'phase_of_play', 'overload', 'in_possession', 96, 96, 'Positional Build-up Play: Practice 13', 'De Zerbi (Brighton)', 'Break through lines from the back and finish quickly against a recovering back four.', 'Low zone: blue back 4, 2 DMs and AM v 6 reds; wingers and forward high up where 4 mannequins stand as the red back line; full goal with GK; each player starts at his marker.', 'Coach passes in; blues keep the ball and find F, who sets for the oncoming AM; then all except the CBs join to attack quickly while 4 reds track back to defend (e.g. AM to RW, who dribbles and crosses low for LW).', 'Centre backs stay; 4 reds recover to defend once the ball reaches F.', NULL, 'Lay-off to the third man then commit numbers forward fast.', '10v6 then 5v4 (+GK)', 17, 18, NULL, NULL, NULL, NULL, true, true, true, NULL, 400),
  ('10v9 three-zone build-up to gates', 'positional_game', 'overload', 'in_possession', 97, 97, 'Positional Build-up Play: Practice 14', 'De Zerbi (Brighton)', 'Build up through three zones using overloads and finish with a through pass into the final zone.', '3 zones: 6v4 in Zone 1, 4v5 in Zone 2, 3 yellow pole gates at the far end of Zone 3 and 3 red gates for the reds; overall 10v9.', 'Blues build through Zones 1 and 2, play a through pass for a runner into Zone 3 and score through a yellow gate; once the ball reaches Zone 2 blue Zone 1 players except CBs can push on. Reds win it and score through their gates.', 'Reds stay in their zones except the 4 defenders who may drop when the ball enters Zone 3; AM may drop into Zone 1 to make 7v4.', NULL, 'Consolidate in Zone 1, lay-off from F, full back deep run to finish.', '10v9', 19, 19, NULL, NULL, NULL, NULL, false, false, true, NULL, 410),
  ('Switch to winger, FB underlap into box', 'combination', 'passive', 'in_possession', 102, 104, 'Attacking Positional Patterns of Play: Set-up 1, Practice 1', 'De Zerbi (Sassuolo)', 'Rehearse a switch to the winger and the full back''s underlapping run in behind to cross for a finish.', 'Patterns set-up 1 (3-2-3 attacking shape, no CBs): 9 players (LB, RB, DM, LCM, RCM, LW, RW, F) with 9 red mannequins in a 4-5 shape, coaches pressuring; 2 players per position form 2 teams who alternate; balls at both full back spots; GK in goal.', 'RB takes a touch under coach pressure and plays to RCM, back to DM who turns and passes diagonally to LCM, out to LW; LW passes into the box for LB''s deep underlapping run inside the full back mannequin; LB crosses low for RW arriving late, with LCM, RCM and F also attacking the box.', 'Teams alternate; finishing team jogs back and the next goes.', NULL, 'Time the underlap and the far-side winger''s run; fill different box areas.', '2 teams of 9 outfield + GK', 10, 19, NULL, NULL, NULL, NULL, true, true, true, NULL, 420),
  ('Switch to winger, FB overlaps into box', 'combination', 'passive', 'in_possession', 105, 105, 'Patterns of Play Set-up 1: Practice 2', 'De Zerbi (Sassuolo)', 'Switching play to the far winger and finishing from a full back''s overlapping run.', 'Attacking half with GK in goal; 9 red mannequins in a compact 4-5 block; 9 attackers in a 3-2-3 attacking shape (FB, DM, two CMs, wingers, F; no centre backs); coaches spread around to feed balls and press or block lanes; ball stacks at two restart spots.', 'RB steps up under the coach''s pressure and finds RCM, who drops and plays back to DM; DM, pressed, plays diagonally to LCM, who finds LW. LW drives inside at the FB mannequin and slips LB in on the overlap; LB cuts back for the forward at the near post.', '2 teams of 10 (2 spare players per position) alternate running the pattern; jog back after finishing.', NULL, 'Timing of the final run; other attackers fill the box (near post, far post, edge) for alternative options; check away before receiving.', '9 attackers + GK vs mannequins and coaches', 20, 20, 'attacking half of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 430),
  ('Switch to winger, CM run in behind', 'combination', 'passive', 'in_possession', 106, 106, 'Patterns of Play Set-up 1: Practice 3', 'De Zerbi (Sassuolo)', 'Switching play and using a central midfielder''s run beyond the line for a cut back.', 'Attacking half with GK in goal; 9 red mannequins in a compact 4-5 block; 9 attackers in a 3-2-3 attacking shape (FB, DM, two CMs, wingers, F; no centre backs); coaches spread around to feed balls and press or block lanes; ball stacks at two restart spots.', 'LB under pressure finds a dropping LCM, who plays back to DM; DM checks, then plays diagonally to RCM on the half-turn, who sends RW wide. RW drives inside and puts RCM in behind; RCM cuts back for LCM arriving at the penalty spot.', '2 teams of 10 (2 spare players per position) alternate running the pattern; jog back after finishing.', NULL, 'Timing of the final run; other attackers fill the box (near post, far post, edge) for alternative options; check away before receiving.', '9 attackers + GK vs mannequins and coaches', 20, 20, 'attacking half of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 440),
  ('Switch via dropping CM when lanes blocked', 'combination', 'passive', 'in_possession', 107, 107, 'Patterns of Play Set-up 1: Practice 4', 'De Zerbi (Sassuolo)', 'Recognising two blocked passing lanes and switching through a dropping midfielder.', 'Attacking half with GK in goal; 9 red mannequins in a compact 4-5 block; 9 attackers in a 3-2-3 attacking shape (FB, DM, two CMs, wingers, F; no centre backs); coaches spread around to feed balls and press or block lanes; ball stacks at two restart spots.', 'Pressed LB cannot go forward so plays back to DM, who plays to LCM dropping to receive; LCM drives inside and switches to RB beyond the mannequin; RB finds RW, who drives at the FB mannequin and slides RCM in behind; RCM squares for the forward to finish.', '2 teams of 10 (2 spare players per position) alternate running the pattern; jog back after finishing.', NULL, 'Timing of the final run; other attackers fill the box (near post, far post, edge) for alternative options; check away before receiving.', '9 attackers + GK vs mannequins and coaches', 20, 20, 'attacking half of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 450),
  ('Central combination, through pass to winger', 'combination', 'passive', 'in_possession', 108, 108, 'Patterns of Play Set-up 1: Practice 5', 'De Zerbi (Sassuolo)', 'Playing through the centre with a forward''s lay-off and a through ball for the far winger.', 'Attacking half with GK in goal; 9 red mannequins in a compact 4-5 block; 9 attackers in a 3-2-3 attacking shape (FB, DM, two CMs, wingers, F; no centre backs); coaches spread around to feed balls and press or block lanes; ball stacks at two restart spots.', 'LB finds a marked LCM, who plays back to DM; DM is pressed so F drifts into the open lane to receive and sets for RCM, who slides RW in behind off the flank to shoot.', '2 teams of 10 (2 spare players per position) alternate running the pattern; jog back after finishing.', NULL, 'Timing of the final run; other attackers fill the box (near post, far post, edge) for alternative options; check away before receiving.', '9 attackers + GK vs mannequins and coaches', 20, 20, 'attacking half of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 460),
  ('Left side give and go with forward', 'combination', 'passive', 'in_possession', 109, 109, 'Patterns of Play Set-up 1: Practice 6', 'De Zerbi (Sassuolo)', 'Breaking the line on the left with the forward''s lay-off and spin in behind.', 'Attacking half with GK in goal; 9 red mannequins in a compact 4-5 block; 9 attackers in a 3-2-3 attacking shape (FB, DM, two CMs, wingers, F; no centre backs); coaches spread around to feed balls and press or block lanes; ball stacks at two restart spots.', 'LB plays to a marked LCM, who goes back to DM; DM is pressed but finds F in front of the CB mannequin; F sets for LCM spinning off his marker, who plays F in behind around the CB mannequin for a 1v1 with the GK.', '2 teams of 10 (2 spare players per position) alternate running the pattern; jog back after finishing.', NULL, 'Timing of the final run; other attackers fill the box (near post, far post, edge) for alternative options; check away before receiving.', '9 attackers + GK vs mannequins and coaches', 20, 20, 'attacking half of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 470),
  ('Right side give and go with forward', 'combination', 'passive', 'in_possession', 110, 110, 'Patterns of Play Set-up 1: Practice 7', 'De Zerbi (Sassuolo)', 'Mirror of the left-side give and go: forward lays off and spins between the centre backs.', 'Attacking half with GK in goal; 9 red mannequins in a compact 4-5 block; 9 attackers in a 3-2-3 attacking shape (FB, DM, two CMs, wingers, F; no centre backs); coaches spread around to feed balls and press or block lanes; ball stacks at two restart spots.', 'RB plays to a marked RCM, back to DM; DM, pressed, finds F dropping across; F sets for RCM who spins away and plays F through between the two CB mannequins for a 1v1 finish.', '2 teams of 10 (2 spare players per position) alternate running the pattern; jog back after finishing.', NULL, 'Timing of the final run; other attackers fill the box (near post, far post, edge) for alternative options; check away before receiving.', '9 attackers + GK vs mannequins and coaches', 20, 20, 'attacking half of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 480),
  ('Strong-side possession, switch, FB overlap', 'combination', 'passive', 'in_possession', 112, 112, 'Patterns of Play Set-up 2: Practice 1', 'De Zerbi (Sassuolo)', 'Keeping the ball on the strong side, then switching the point of attack to the far winger for the full back''s overlap.', 'Attacking half with GK in goal; 9 red mannequins in a compact 4-5 block; 9 attackers in a 3-2-3 attacking shape (FB, DM, two CMs, wingers, F; no centre backs); coaches spread around to feed balls and press or block lanes; ball stacks at two restart spots.', 'RB to RW, inside to RCM, set back for RW who carries inside and returns it to DM; DM carries and switches with an aerial ball to LW, who drives inside and feeds LB on the overlap; LB squares for F at the centre of the box.', '2 teams of 10 (2 spare players per position) alternate running the pattern; jog back after finishing.', NULL, 'Timing of the final run; other attackers fill the box (near post, far post, edge) for alternative options; check away before receiving.', '9 attackers + GK vs mannequins and coaches', 20, 20, 'attacking half of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 490),
  ('Strong-side possession, switch, CM runs beyond', 'combination', 'passive', 'in_possession', 113, 113, 'Patterns of Play Set-up 2: Practice 2', 'De Zerbi (Sassuolo)', 'Strong-side combination then switch, finished by the far central midfielder''s penetrating run.', 'Attacking half with GK in goal; 9 red mannequins in a compact 4-5 block; 9 attackers in a 3-2-3 attacking shape (FB, DM, two CMs, wingers, F; no centre backs); coaches spread around to feed balls and press or block lanes; ball stacks at two restart spots.', 'RB-RW-RCM-RW combination on the right; the coach presses RW into passing to DM; DM carries and switches in the air to LW, who drives inside and plays LCM in behind; LCM squares for RCM arriving in the box.', '2 teams of 10 (2 spare players per position) alternate running the pattern; jog back after finishing.', NULL, 'Timing of the final run; other attackers fill the box (near post, far post, edge) for alternative options; check away before receiving.', '9 attackers + GK vs mannequins and coaches', 20, 20, 'attacking half of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 500),
  ('Strong-side possession, switch, lay-off and overlap', 'combination', 'passive', 'in_possession', 114, 114, 'Patterns of Play Set-up 2: Practice 3', 'De Zerbi (Sassuolo)', 'Switching play then combining with a lay-off from the winger and a deep full back overlap.', 'Attacking half with GK in goal; 9 red mannequins in a compact 4-5 block; 9 attackers in a 3-2-3 attacking shape (FB, DM, two CMs, wingers, F; no centre backs); coaches spread around to feed balls and press or block lanes; ball stacks at two restart spots.', 'Same right-side opening to DM, who switches to LW; LW touches inside and lays to the onrushing LCM, who plays LB in behind on the deep overlap; LB cuts back for F.', '2 teams of 10 (2 spare players per position) alternate running the pattern; jog back after finishing.', NULL, 'Timing of the final run; other attackers fill the box (near post, far post, edge) for alternative options; check away before receiving.', '9 attackers + GK vs mannequins and coaches', 20, 20, 'attacking half of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 510),
  ('Central possession, lay-off, through ball to strong-side winger', 'combination', 'passive', 'in_possession', 115, 115, 'Patterns of Play Set-up 2: Practice 4', 'De Zerbi (Sassuolo)', 'Circulating in the centre and using the forward''s set to release the near winger diagonally.', 'Attacking half with GK in goal; 9 red mannequins in a compact 4-5 block; 9 attackers in a 3-2-3 attacking shape (FB, DM, two CMs, wingers, F; no centre backs); coaches spread around to feed balls and press or block lanes; ball stacks at two restart spots.', 'LB to DM, pressed DM plays to dropping LCM; LCM shifts it to RCM, who sets back to DM; DM finds F, who sets for LCM; LCM threads a pass between FB and CB mannequins for LW''s diagonal run to shoot across the GK.', '2 teams of 10 (2 spare players per position) alternate running the pattern; jog back after finishing.', NULL, 'Timing of the final run; other attackers fill the box (near post, far post, edge) for alternative options; check away before receiving.', '9 attackers + GK vs mannequins and coaches', 20, 20, 'attacking half of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 520),
  ('Central possession, lay-off, through ball to weak-side winger', 'combination', 'passive', 'in_possession', 116, 116, 'Patterns of Play Set-up 2: Practice 5', 'De Zerbi (Sassuolo)', 'Central circulation ending in a diagonal through ball to the far winger, who squares to the forward.', 'Attacking half with GK in goal; 9 red mannequins in a compact 4-5 block; 9 attackers in a 3-2-3 attacking shape (FB, DM, two CMs, wingers, F; no centre backs); coaches spread around to feed balls and press or block lanes; ball stacks at two restart spots.', 'RB to DM, pressed DM finds RCM; RCM to LCM and back to DM; DM to F, who sets for RCM; RCM plays diagonally between the CB mannequins for LW running inside the FB, and LW squares for F.', '2 teams of 10 (2 spare players per position) alternate running the pattern; jog back after finishing.', NULL, 'Timing of the final run; other attackers fill the box (near post, far post, edge) for alternative options; check away before receiving.', '9 attackers + GK vs mannequins and coaches', 20, 20, 'attacking half of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 530),
  ('Central possession, forward turns and plays winger in', 'combination', 'passive', 'in_possession', 117, 117, 'Patterns of Play Set-up 2: Practice 6', 'De Zerbi (Sassuolo)', 'Using the forward''s turn after central circulation to slip the winger between the lines.', 'Attacking half with GK in goal; 9 red mannequins in a compact 4-5 block; 9 attackers in a 3-2-3 attacking shape (FB, DM, two CMs, wingers, F; no centre backs); coaches spread around to feed balls and press or block lanes; ball stacks at two restart spots.', 'RB to DM, pressed DM plays to RCM under pressure; RCM to LCM, set back to DM; DM finds F, who turns and plays diagonally between the CB mannequins for LW, who shoots.', '2 teams of 10 (2 spare players per position) alternate running the pattern; jog back after finishing.', NULL, 'Timing of the final run; other attackers fill the box (near post, far post, edge) for alternative options; check away before receiving.', '9 attackers + GK vs mannequins and coaches', 20, 20, 'attacking half of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 540),
  ('Short combination, lay-off, CM through ball, cut back', 'combination', 'passive', 'in_possession', 118, 118, 'Patterns of Play Set-up 2: Practice 7', 'De Zerbi (Sassuolo)', 'Breaking the line with a short combination, a lay-off and a through ball for the winger to cut back.', 'Attacking half with GK in goal; 9 red mannequins in a compact 4-5 block; 9 attackers in a 3-2-3 attacking shape (FB, DM, two CMs, wingers, F; no centre backs); coaches spread around to feed balls and press or block lanes; ball stacks at two restart spots.', 'RB to DM, pressed DM to RCM; RCM to LCM who sets for DM moving round the coach; DM finds F, who sets for LCM; LCM plays LW in between FB and CB mannequins and LW squares for F.', '2 teams of 10 (2 spare players per position) alternate running the pattern; jog back after finishing.', NULL, 'Timing of the final run; other attackers fill the box (near post, far post, edge) for alternative options; check away before receiving.', '9 attackers + GK vs mannequins and coaches', 20, 20, 'attacking half of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 550),
  ('Switch to overlapping FB, reset, give and go', 'combination', 'passive', 'in_possession', 119, 119, 'Patterns of Play Set-up 2: Practice 8', 'De Zerbi (Sassuolo)', 'Switching to the far side, resetting when blocked and finishing with a midfielder''s give and go.', 'Attacking half with GK in goal; 9 red mannequins in a compact 4-5 block; 9 attackers in a 3-2-3 attacking shape (FB, DM, two CMs, wingers, F; no centre backs); coaches spread around to feed balls and press or block lanes; ball stacks at two restart spots.', 'LB to a dropping LCM under pressure, back to DM who carries and plays diagonally to RCM; RCM to RW, who drives inside and finds RB overlapping; RB turns back and plays RCM shifting wide; RCM dribbles in, plays a one-two with F and cuts back for LW to score.', '2 teams of 10 (2 spare players per position) alternate running the pattern; jog back after finishing.', NULL, 'Timing of the final run; other attackers fill the box (near post, far post, edge) for alternative options; check away before receiving.', '9 attackers + GK vs mannequins and coaches', 20, 20, 'attacking half of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 560),
  ('Switch to RB overlap, reset, lofted ball into box', 'combination', 'passive', 'in_possession', 120, 120, 'Patterns of Play Set-up 2: Practice 9', 'De Zerbi (Sassuolo)', 'Switch to the right, reset when the overlap is blocked, then a lofted pass into the box.', 'Attacking half with GK in goal; 9 red mannequins in a compact 4-5 block; 9 attackers in a 3-2-3 attacking shape (FB, DM, two CMs, wingers, F; no centre backs); coaches spread around to feed balls and press or block lanes; ball stacks at two restart spots.', 'LB to LCM, who drops under pressure and plays DM; DM carries and finds RCM, who sends RW wide; RW drives in and plays RB on the overlap; RB turns and returns to RCM by the touchline, who lofts a diagonal ball into the box for LW to finish.', '2 teams of 10 (2 spare players per position) alternate running the pattern; jog back after finishing.', NULL, 'Timing of the final run; other attackers fill the box (near post, far post, edge) for alternative options; check away before receiving.', '9 attackers + GK vs mannequins and coaches', 20, 20, 'attacking half of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 570),
  ('Switch to LB overlap, reset, lofted ball into box', 'combination', 'passive', 'in_possession', 121, 121, 'Patterns of Play Set-up 2: Practice 10', 'De Zerbi (Sassuolo)', 'Mirror on the left: switch, reset when blocked and lofted ball into the box.', 'Attacking half with GK in goal; 9 red mannequins in a compact 4-5 block; 9 attackers in a 3-2-3 attacking shape (FB, DM, two CMs, wingers, F; no centre backs); coaches spread around to feed balls and press or block lanes; ball stacks at two restart spots.', 'RB to RCM under pressure, back to DM who carries and plays diagonally to LCM; LCM to LW, who drives inside and finds LB overlapping; LB turns back and plays LCM, who lofts a diagonal pass into the box for RCM to score.', '2 teams of 10 (2 spare players per position) alternate running the pattern; jog back after finishing.', NULL, 'Timing of the final run; other attackers fill the box (near post, far post, edge) for alternative options; check away before receiving.', '9 attackers + GK vs mannequins and coaches', 20, 20, 'attacking half of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 580),
  ('Wide combination, reset to CB, attack flank', 'combination', 'passive', 'in_possession', 124, 124, 'Patterns of Play Set-up 3: Practice 1', 'De Zerbi (Sassuolo)', 'Combining wide, resetting through a centre back and then attacking down the same flank.', 'Attacking half with GK; 9 red mannequins in a 4-5 block; 10 outfield attackers in a 2-3-2-3 shape (2 CBs, FBs, DM, two CMs, wingers, F); coaches press and block lanes; two restart spots with balls.', 'RB-RW-RCM-RB combination, RB returns it to CB; CB plays a one-two with a pressed DM; DM carries and finds RCM, who turns and plays RW; RW drives inside and slips RB on the deep overlap to cut back for F.', '2 teams of 10 (2 spare players per position) alternate running the pattern; jog back after finishing.', NULL, 'Timing of the final run; other attackers fill the box (near post, far post, edge) for alternative options; check away before receiving.', '10 attackers + GK vs mannequins and coaches', 22, 22, 'attacking half of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 590),
  ('Wide combination, reset, attack centre via target forward', 'combination', 'passive', 'in_possession', 125, 125, 'Patterns of Play Set-up 3: Practice 2', 'De Zerbi (Sassuolo)', 'Resetting through both centre backs then playing through the centre using the forward as a target.', 'Attacking half with GK; 9 red mannequins in a 4-5 block; 10 outfield attackers in a 2-3-2-3 shape (2 CBs, FBs, DM, two CMs, wingers, F); coaches press and block lanes; two restart spots with balls.', 'Right-side combination resets to CB, who plays across to the other CB under pressure; second CB carries and finds DM; pressed DM plays to LCM, who turns and passes between the CB mannequins to F; F sets for LCM to shoot.', '2 teams of 10 (2 spare players per position) alternate running the pattern; jog back after finishing.', NULL, 'Timing of the final run; other attackers fill the box (near post, far post, edge) for alternative options; check away before receiving.', '10 attackers + GK vs mannequins and coaches', 22, 22, 'attacking half of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 600),
  ('Reset to CB, CM through ball to winger', 'combination', 'passive', 'in_possession', 126, 126, 'Patterns of Play Set-up 3: Practice 3', 'De Zerbi (Sassuolo)', 'Resetting to a centre back and attacking through the centre with a midfielder''s through pass to the winger.', 'Attacking half with GK; 9 red mannequins in a 4-5 block; 10 outfield attackers in a 2-3-2-3 shape (2 CBs, FBs, DM, two CMs, wingers, F); coaches press and block lanes; two restart spots with balls.', 'RB plays RCM, who returns it to a marked DM; DM finds RB dropping to receive and RB resets to CB; CB plays DM in a deep pocket, back to the other CB who carries under pressure and finds RCM; RCM turns and plays RW in behind between FB and CB mannequins to shoot.', '2 teams of 10 (2 spare players per position) alternate running the pattern; jog back after finishing.', NULL, 'Timing of the final run; other attackers fill the box (near post, far post, edge) for alternative options; check away before receiving.', '10 attackers + GK vs mannequins and coaches', 22, 22, 'attacking half of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 610),
  ('Quick combination, switch via both CBs, FB overlap', 'combination', 'passive', 'in_possession', 127, 127, 'Patterns of Play Set-up 3: Practice 4', 'De Zerbi (Sassuolo)', 'Quick right-side combination then switching through both centre backs to the far winger and overlapping full back.', 'Attacking half with GK; 9 red mannequins in a 4-5 block; 10 outfield attackers in a 2-3-2-3 shape (2 CBs, FBs, DM, two CMs, wingers, F); coaches press and block lanes; two restart spots with balls.', 'RB-RW-RCM-RW-RB combination, RB resets to CB under pressure; CB to DM in a deep spot, back to the other CB who carries forward and finds LCM; LCM turns to LW, who drives inside and puts LB in behind; LB cuts back for F.', '2 teams of 10 (2 spare players per position) alternate running the pattern; jog back after finishing.', NULL, 'Timing of the final run; other attackers fill the box (near post, far post, edge) for alternative options; check away before receiving.', '10 attackers + GK vs mannequins and coaches', 22, 22, 'attacking half of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 620),
  ('Triangle, switch via CB to winger, give and go', 'combination', 'passive', 'in_possession', 128, 128, 'Patterns of Play Set-up 3: Practice 5', 'De Zerbi (Sassuolo)', 'Two-touch triangle on the left then switching through a high centre back to the right winger.', 'Attacking half with GK; 9 red mannequins in a 4-5 block; 10 outfield attackers in a 2-3-2-3 shape (2 CBs, FBs, DM, two CMs, wingers, F); coaches press and block lanes; two restart spots with balls.', 'Two-touch triangle LB-DM-LCM-DM with DM dropping off his marker; DM finds a CB who has pushed past halfway, who carries and passes to RW on the touchline; RW drives inside and plays a one-two with RCM, then squares across the box for F at the far post.', '2 teams of 10 (2 spare players per position) alternate running the pattern; jog back after finishing.', NULL, 'Timing of the final run; other attackers fill the box (near post, far post, edge) for alternative options; check away before receiving.', '10 attackers + GK vs mannequins and coaches', 22, 22, 'attacking half of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 630),
  ('Triangle, DM switches to winger, FB overlap', 'combination', 'passive', 'in_possession', 129, 129, 'Patterns of Play Set-up 3: Practice 6', 'De Zerbi (Sassuolo)', 'One-touch triangle on the left, then the DM switches straight to the far winger for the overlapping full back.', 'Attacking half with GK; 9 red mannequins in a 4-5 block; 10 outfield attackers in a 2-3-2-3 shape (2 CBs, FBs, DM, two CMs, wingers, F); coaches press and block lanes; two restart spots with balls.', 'One-touch triangle LB-DM-LCM-DM, DM opens up and carries into space, then switches in the air to RW on the touchline; RW drives inside and slips RB on the deep overlap; RB cuts back for F.', '2 teams of 10 (2 spare players per position) alternate running the pattern; jog back after finishing.', NULL, 'Timing of the final run; other attackers fill the box (near post, far post, edge) for alternative options; check away before receiving.', '10 attackers + GK vs mannequins and coaches', 22, 22, 'attacking half of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 640),
  ('Double switch via CB and DM, 5v2 wide zones', 'combination', 'overload', 'in_possession', 132, 132, 'Patterns of Play Set-up 4: Practice 1', 'De Zerbi (Sassuolo)', 'Switching play twice through the centre back and DM while keeping the ball in the 5v2 wide zones.', 'Attacking half with GK; 6 red mannequins (back 4 and 2 CMs) plus 2 live red full backs and 2 live red wingers; both flanks marked as 5v2 wide zones that the red wide players must stay inside; 10 attackers in a 2-3-2-3 shape (4-3-3); only a set group of attackers may enter each wide zone at once.', 'RB-CB-CB circulation, CB to DM who turns and finds LCM, who returns it; DM to LW, one-two with LB, CB moves wide into the zone to receive and plays DM; DM opens up to the other CB, who carries past halfway and finds RW; RW drives in and plays RCM in behind to square for F.', 'Red wide players must stay in their 5v2 zone; at most 5 attackers in a wide zone at a time and only named players may enter.', NULL, 'Timing of the final run; other attackers fill the box (near post, far post, edge) for alternative options; check away before receiving.', '10 attackers + GK vs 6 mannequins + 4 live wide defenders', 15, 15, 'attacking half of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 650),
  ('Right flank 5v2 possession, through ball to forward', 'combination', 'overload', 'in_possession', 133, 133, 'Patterns of Play Set-up 4: Practice 2', 'De Zerbi (Sassuolo)', 'Keeping the ball in the right 5v2 zone, then finishing with a through pass for the forward.', 'Attacking half with GK; 6 red mannequins (back 4 and 2 CMs) plus 2 live red full backs and 2 live red wingers; both flanks marked as 5v2 wide zones that the red wide players must stay inside; 10 attackers in a 2-3-2-3 shape (4-3-3); only a set group of attackers may enter each wide zone at once.', 'LB-CB-CB circulation, CB to DM who moves across, to RB, RW, inside to RCM on a curved run, back to CB to reset; CB to DM on the half-turn who carries forward and finds LCM facing forward; LCM plays F in behind between the CB mannequins.', 'Red wide players must stay in their 5v2 zone; at most 5 attackers in a wide zone at a time and only named players may enter.', NULL, 'Timing of the final run; other attackers fill the box (near post, far post, edge) for alternative options; check away before receiving.', '10 attackers + GK vs 6 mannequins + 4 live wide defenders', 15, 15, 'attacking half of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 660),
  ('Left flank 5v2 possession, through ball to forward', 'combination', 'overload', 'in_possession', 134, 134, 'Patterns of Play Set-up 4: Practice 3', 'De Zerbi (Sassuolo)', 'Possession in the left 5v2 zone then switching and finishing with a through ball to the forward.', 'Attacking half with GK; 6 red mannequins (back 4 and 2 CMs) plus 2 live red full backs and 2 live red wingers; both flanks marked as 5v2 wide zones that the red wide players must stay inside; 10 attackers in a 2-3-2-3 shape (4-3-3); only a set group of attackers may enter each wide zone at once.', 'RB-CB-CB, CB to DM who finds LB, LB to LW; LW inside to LCM who moved into the zone, back to CB, LB, DM; DM opens up, carries and plays diagonally to RCM, who touches forward and plays F through between the CB mannequins.', 'Red wide players must stay in their 5v2 zone; at most 5 attackers in a wide zone at a time and only named players may enter.', NULL, 'Timing of the final run; other attackers fill the box (near post, far post, edge) for alternative options; check away before receiving.', '10 attackers + GK vs 6 mannequins + 4 live wide defenders', 15, 15, 'attacking half of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 670),
  ('Right flank 5v2, forward''s give and go', 'combination', 'overload', 'in_possession', 135, 135, 'Patterns of Play Set-up 4: Practice 4', 'De Zerbi (Sassuolo)', 'Right-side possession then attacking the centre with the forward''s give and go.', 'Attacking half with GK; 6 red mannequins (back 4 and 2 CMs) plus 2 live red full backs and 2 live red wingers; both flanks marked as 5v2 wide zones that the red wide players must stay inside; 10 attackers in a 2-3-2-3 shape (4-3-3); only a set group of attackers may enter each wide zone at once.', 'LB-CB-CB, CB to RB, inside to DM, to RCM, RW and back to CB moving forward; DM shifts into the centre, receives and carries before finding F, who has come across to receive back to goal; F plays a give and go with LCM, who spins between the CB mannequins to shoot.', 'Red wide players must stay in their 5v2 zone; at most 5 attackers in a wide zone at a time and only named players may enter.', NULL, 'Timing of the final run; other attackers fill the box (near post, far post, edge) for alternative options; check away before receiving.', '10 attackers + GK vs 6 mannequins + 4 live wide defenders', 15, 15, 'attacking half of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 680),
  ('Left flank 5v2, forward''s wall pass', 'combination', 'overload', 'in_possession', 136, 136, 'Patterns of Play Set-up 4: Practice 5', 'De Zerbi (Sassuolo)', 'Left-side possession then breaking through the centre with the forward''s wall pass for the winger.', 'Attacking half with GK; 6 red mannequins (back 4 and 2 CMs) plus 2 live red full backs and 2 live red wingers; both flanks marked as 5v2 wide zones that the red wide players must stay inside; 10 attackers in a 2-3-2-3 shape (4-3-3); only a set group of attackers may enter each wide zone at once.', 'RB-CB-CB, CB carries to DM and wide to the coach in the LB spot, on to LW; LW inside to LCM in the zone, back to CB, coach, DM; DM shifts, opens up and plays vertically to F, who plays a wall pass between the CB mannequins for RW running in behind to score.', 'Red wide players must stay in their 5v2 zone; at most 5 attackers in a wide zone at a time and only named players may enter.', NULL, 'Timing of the final run; other attackers fill the box (near post, far post, edge) for alternative options; check away before receiving.', '10 attackers + GK vs 6 mannequins + 4 live wide defenders', 15, 15, 'attacking half of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 690),
  ('Left flank 5v2, switch to overlapping RB', 'combination', 'overload', 'in_possession', 137, 137, 'Patterns of Play Set-up 4: Practice 6', 'De Zerbi (Sassuolo)', 'Possession in the left zone then a switch to the right winger for the right back''s deep overlap.', 'Attacking half with GK; 6 red mannequins (back 4 and 2 CMs) plus 2 live red full backs and 2 live red wingers; both flanks marked as 5v2 wide zones that the red wide players must stay inside; 10 attackers in a 2-3-2-3 shape (4-3-3); only a set group of attackers may enter each wide zone at once.', 'RB-CB-CB, CB moves into the left zone and plays LCM to LW; LW back to LB, inside to LCM and back into DM; DM moves inside and switches in the air to RW; RW comes inside to RCM, who slips RB in on the deep overlap; RB cuts back for F.', 'Red wide players must stay in their 5v2 zone; at most 5 attackers in a wide zone at a time and only named players may enter.', NULL, 'Timing of the final run; other attackers fill the box (near post, far post, edge) for alternative options; check away before receiving.', '10 attackers + GK vs 6 mannequins + 4 live wide defenders', 15, 15, 'attacking half of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 700),
  ('Back-line circulation, inverted forwards (3-4-3)', 'combination', 'overload', 'in_possession', 138, 138, 'Patterns of Play Set-up 4: Practice 7', 'De Zerbi (Sassuolo)', 'Passing across a back three and attacking the centre with inside forwards in a 3-4-3.', 'Attacking half with GK; 6 red mannequins (back 4 and 2 CMs) plus 2 live red full backs and 2 live red wingers; both flanks marked as 5v2 wide zones that the red wide players must stay inside; 10 attackers in a 2-3-2-3 shape (4-3-3); only a set group of attackers may enter each wide zone at once.', 'RWB to RCB, across to CB and LCB; LCB carries under pressure from the red opponent and finds RCM, who has shifted left; RCM plays diagonally to RF, who carries and plays a give and go with F to get in behind and score.', 'Red wide players must stay in their 5v2 zone; at most 5 attackers in a wide zone at a time and only named players may enter.', 'Uses a 3-4-3 shape: back three with wing backs and two inverted forwards.', 'Timing of the final run; other attackers fill the box (near post, far post, edge) for alternative options; check away before receiving.', '10 attackers in a 3-4-3 + GK vs mannequins + live wide defenders', 15, 15, 'attacking half of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 710),
  ('3-player flank combination, FB third man run', 'combination', 'unopposed', 'in_possession', 141, 141, 'Attacking Combinations and Finishing: Practice 1', 'De Zerbi (Brighton)', 'Finishing a third-man run by the full back off a winger-midfielder combination.', 'Box and edge of the area with GK; 2 red mannequins as centre backs, blue mannequins as markers, cones for runs; coach (De Zerbi) feeds and works one side then the other.', 'DM plays wide to RW, who checks off the cone; RW carries inside and finds AM coming off his cone; AM plays RB through between the two red mannequins; RB cuts back into the centre for F, who arcs round his cone to finish.', NULL, 'Rotate DM > RB > RW > AM > F > DM; also run on the left side.', 'Check away before receiving, time the final run around the cone or mannequin, finish first time from the cut back.', '5 attackers + GK', NULL, NULL, 'final third / penalty area', NULL, NULL, NULL, true, true, true, NULL, 720),
  ('Wide combination with FB overlap and cut back (1)', 'combination', 'unopposed', 'in_possession', 142, 142, 'Attacking Combinations and Finishing: Practice 2', 'De Zerbi (Sassuolo)', 'Building a wide combination that frees the full back on the overlap to cut back.', 'Box and edge of the area with GK; 2 red mannequins as centre backs, blue mannequins as markers, cones for runs; coach (De Zerbi) feeds and works one side then the other.', 'AM plays to DM coming off his mannequin, DM opens up and finds RB dropping off; RB touches past the mannequin and plays RW, who checks away; RW plays inside for AM, who slides RB in behind on the deep overlap; RB cuts back to the penalty spot for F.', NULL, 'Rotate AM > DM > RB > RW > F; also run on the left side.', 'Check away before receiving, time the final run around the cone or mannequin, finish first time from the cut back.', '5 attackers + GK', NULL, NULL, 'final third / penalty area', NULL, NULL, NULL, true, true, true, NULL, 730),
  ('Wide combination with FB overlap and cut back (2)', 'combination', 'unopposed', 'in_possession', 143, 143, 'Attacking Combinations and Finishing: Practice 3', 'De Zerbi (Sassuolo)', 'Variation of the wide combination with a two-touch DM and the winger finding the AM.', 'Box and edge of the area with GK; 2 red mannequins as centre backs, blue mannequins as markers, cones for runs; coach (De Zerbi) feeds and works one side then the other.', 'AM to DM moving inside off the mannequin, DM to RB dropping off; RB touches past the mannequin and finds RW, who touches inside for AM checking away; AM plays RB through on the deep overlap; RB cuts back for F at the penalty spot.', NULL, 'Rotate AM > DM > RB > RW > F; also run on the left side.', 'Check away before receiving, time the final run around the cone or mannequin, finish first time from the cut back.', '5 attackers + GK', NULL, NULL, 'final third / penalty area', NULL, NULL, NULL, true, true, true, NULL, 740),
  ('One-two, FB underlap third man run, cut back', 'combination', 'unopposed', 'in_possession', 144, 144, 'Attacking Combinations and Finishing: Practice 4', 'De Zerbi (Sassuolo)', 'Finishing an inside (underlapping) third-man run by the full back after a one-two.', 'Box and edge of the area with GK; 2 red mannequins as centre backs, blue mannequins as markers, cones for runs; coach (De Zerbi) feeds and works one side then the other.', 'AM and DM play a one-two, AM goes back to RB dropping off; RB plays DM, who drops and turns and goes wide to RW checking away; RW touches inside and plays RB on the deep underlap between the red mannequins; RB cuts back to the penalty spot for F.', NULL, 'Rotate AM > DM > RB > RW > F; also run on the left side.', 'Check away before receiving, time the final run around the cone or mannequin, finish first time from the cut back.', '5 attackers + GK', NULL, NULL, 'final third / penalty area', NULL, NULL, NULL, true, true, true, NULL, 750),
  ('Pass wide, set, FB deep run, low cross', 'combination', 'unopposed', 'in_possession', 145, 145, 'Attacking Combinations and Finishing: Practice 5', 'De Zerbi (Benevento)', 'Releasing the full back''s deep third-man run in behind and finishing a low cross.', 'Box and edge of the area with GK; 2 red mannequins as centre backs, blue mannequins as markers, cones for runs; coach (De Zerbi) feeds and works one side then the other.', 'Coach plays RB off his mannequin; RB opens and plays RW, who checks away; RW touches inside for AM on the run; AM slides RB in behind on a deep third-man run; RB crosses low across the box for F, who curls round his mannequin to finish.', NULL, 'No rotation, players repeat their own role; worked on the right then the left.', 'Check away before receiving, time the final run around the cone or mannequin, finish first time from the cut back.', '4 attackers + coach + GK', NULL, NULL, 'final third / penalty area', NULL, NULL, NULL, true, true, true, NULL, 760),
  ('Forward back to goal, through ball for winger', 'combination', 'passive', 'in_possession', 146, 146, 'Attacking Combinations and Finishing: Practice 6', 'De Zerbi (Sassuolo)', 'Playing through the centre with the forward''s back-to-goal support and a through ball for the winger''s curved run.', 'Edge of the box and centre with GK; FB and CB mannequins in a back line, blue marker mannequins, cones; De Zerbi acts as a defender blocking the lane to the forward.', 'Coach plays DM, who opens up; De Zerbi blocks the straight pass to F, so F drops off his cone for an angle and DM plays him; F sets for RCM, who plays RW through between FB and CB mannequins on a curved run; RW cuts back for F, with LCM and LW also arriving.', NULL, NULL, 'Check away before receiving, time the final run around the cone or mannequin, finish first time from the cut back.', '6 attackers + coach-defender + GK', NULL, NULL, 'final third / penalty area', NULL, NULL, NULL, true, true, true, NULL, 770),
  ('Through the centre, CM third man run', 'combination', 'passive', 'in_possession', 147, 147, 'Attacking Combinations and Finishing: Practice 7', 'De Zerbi (Sassuolo)', 'Playing through the centre so the far central midfielder makes a third-man run to finish.', 'Edge of the box and centre with GK; back-line mannequins and marker mannequins; De Zerbi blocks the lane from DM to F.', 'Coach plays DM, who opens up while De Zerbi blocks the direct lane; F moves diagonally off his cone and DM finds him; F plays diagonally between the CB mannequins for RCM''s third-man run, who finishes past the GK while LCM, wingers and F fill the box.', NULL, NULL, 'Check away before receiving, time the final run around the cone or mannequin, finish first time from the cut back.', '6 attackers + coach-defender + GK', NULL, NULL, 'final third / penalty area', NULL, NULL, NULL, true, true, true, NULL, 780),
  ('Short passing combination 3-station finishing circuit', 'finishing', 'unopposed', 'in_possession', 148, 148, 'Attacking Combinations and Finishing: Practice 8', 'De Zerbi (Brighton)', 'Short one-two and set combinations around mannequins ending in a shot, run at three stations in parallel.', 'Three goals with GKs side by side across the end line; three stations (A, B, C) set out in front of them with mannequins and cones; groups of 5 per station.', 'A: A one-twos with B, plays C off his mannequin, C goes round the mannequin and one-twos with D, who shoots. B: A one-twos with B, plays C, who sets for B to play across to D, who drives at goal and shoots. C: A plays B, one-two with C, B plays across to D, who sets for C to play D through ahead of the mannequin to shoot.', NULL, 'Groups move to the next station after a set time.', 'Sharp one-twos, receive off the mannequin, shoot early.', 'groups of 5, 3 stations (15 + 3 GKs)', 15, 18, NULL, NULL, NULL, NULL, true, true, true, NULL, 790)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
